// Feed catalogue — edit here to add/remove sources.
// Keep list small for MVP; scale via the Scraper OpenClaw skill later.
const feeds = [
  { feedUrl: 'https://tuoitre.vn/rss/kinh-doanh.rss', source: 'rss:tuoitre-kinh-doanh', topic: 'business' },
  { feedUrl: 'https://vnexpress.net/rss/kinh-doanh.rss', source: 'rss:vnexpress-business', topic: 'business' },
  { feedUrl: 'https://cafef.vn/thi-truong-chung-khoan.rss', source: 'rss:cafef-stock', topic: 'finance' }
];
return feeds.map(f => ({ json: f }));

// Runs ONCE per RSS article. Pairs back to the originating Feed catalogue
// entry via n8n pairedItem tracking, so each article carries the correct
// source/topic even though RSS Read emitted a mixed stream of 3N items.
const crypto = require('crypto');
const feed   = $('Feed catalogue').item.json;
const it     = $json;
const title  = (it.title || '').trim();
const link   = (it.link || it.guid || '').trim();
const body   = (it.contentSnippet || it.description || it.content || '').trim();
if (!title || !body) { return null; }
const hash = crypto.createHash('sha256')
  .update(`${link || title}::${body.slice(0, 200)}`)
  .digest('hex');
return { json: {
  orgId:         $env.ZALOCRM_ORG_ID,
  source:        feed.source,
  topic:         feed.topic,
  canonicalUrl:  link || null,
  title,
  body,
  heroImageUrl:  it.enclosure?.url || null,
  publishedAt:   it.isoDate || it.pubDate || new Date().toISOString(),
  dedupeHash:    hash,
  raw:           { ...it, topic: feed.topic }
}};

